 gap=('___ what you said, the album did not top the charts.','Ao contrário do que você disse, o álbum não liderou as paradas.',['Contrary to','Contrary of','Against to'],'Contrary to what/to + substantivo = ao contrário de.'),
 gap2=('The data ___ otherwise.','Os dados sugerem o contrário.',['suggest','suggests','suggesting'],'Data é tratado no plural em contexto formal; suggest sem -s.'),
 gap3=('That overlooks the ___ that the survey was small.','Isso ignora o fato de que a pesquisa era pequena.',['fact','fake','fault'],'Overlook the fact that = ignorar o fato de que.'),
